import sys, time, json, subprocess; sys.path.insert(0,'/workspace')
from wire import v
def initial(pn,payload):
    return bytes([0xc0])+b'\0\0\0\1'+b'\x01\xaa'+b'\x01\xbb'+v(0)+v(1+len(payload))+pn.to_bytes(1,'big')+payload
def ack_frame(largest, first, pairs):
    body=b'\x03'+v(largest)+v(0)+v(len(pairs))+v(first)
    for gap,rng in pairs: body+=v(gap)+v(rng)
    return body+v(0)+v(0)+v(0)
def pairs_desc(largest, first, n):
    pl=[]; low=largest-first
    for k in range(n):
        high=low-1-2
        if high<1 or 1>high: break
        pl.append((2,1)); low=high-1
    return pl
envs=[]; pn=0; largest=1<<45
for i in range(4000):
    first=1999
    largest=largest-2000
    fr=ack_frame(largest,first,pairs_desc(largest,first,1999))
    envs.append(initial(pn%256,fr)); pn+=1
CH=200; events=[]
for i in range(0,len(envs),CH):
    events.append({'datagram':{'wire':b''.join(envs[i:i+CH]).hex(),'auth':[0]*min(CH,len(envs)-i)}})
wire=sum(len(e) for e in envs)
batch={'traces':[{'limits':{'connection':4611686018427387903,'stream':4611686018427387903,'bidi':2**60,'uni':2**60,'cids':4},
                  'local':{'bidi':2,'uni':2,'cids':['aa','bb']},'peer':{'cid':'cc','token':'00'*16},
                  'received':{'I':None,'H':None,'A':None},'events':events}]}
data=json.dumps(batch).encode()
t0=time.time()
p=subprocess.run(['python3','/workspace/run.py','/workspace/tmp/classes'],input=data,capture_output=True)
t1=time.time()
out=json.loads(p.stdout.decode())
if 'traces' not in out: print('INPUT error',out)
else:
    r=out['traces'][0]
    print('wire',wire,'packets',len(envs),'jsonMiB',round(len(data)/2**20,1),'time',round(t1-t0,2),
          'intervals',r['acknowledged'][0]['intervals'],'count',r['acknowledged'][0]['count'],'prefix',r['acknowledged'][0]['prefix'])
EOF
